  --line: #d4d4d4;
  --accent: #0b5cad;
  --surface: #eef0f2;
  --error: #a40000;
  --ok: #1d6b33;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  color: var(--ink);
  background: #fff;
  line-height: 1.5;
}

h1, h2, h3, p, ul, ol, blockquote { margin: 0; }
h1 { font-size: 1.9rem; line-height: 1.2; margin-bottom: 0.5rem; }
h2 { font-size: 1.25rem; margin-bottom: 1rem; }
h3 { font-size: 1rem; }

a { color: var(--ink); }

:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }

.container { max-width: 1180px; margin: 0 auto; padding: 0 24px; }
.plain-list { list-style: none; padding: 0; display: grid; gap: 0.5rem; }

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  margin: -1px; padding: 0; border: 0;
  overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%);
  white-space: nowrap;
}

/* Header */
.site-header { border-bottom: 1px solid var(--line); }
.site-header__inner { display: flex; justify-content: space-between; align-items: center; padding-top: 16px; padding-bottom: 16px; }
.logo { font-size: 1.4rem; font-weight: 800; letter-spacing: 0.02em; text-decoration: none; }
.cart-link { text-decoration: none; font-weight: 600; }
.cart-count {
  display: inline-block; min-width: 1.6em; padding: 0 6px; border-radius: 999px;
  background: var(--ink); color: #fff; text-align: center; font-size: 0.85rem;
}

/* Breadcrumb */
.breadcrumb { padding: 16px 0; font-size: 0.9rem; }
.breadcrumb ol { display: flex; flex-wrap: wrap; gap: 0; list-style: none; padding: 0; margin: 0; }
.breadcrumb li + li::before { content: '/'; padding: 0 8px; color: var(--muted); }
.breadcrumb a { color: var(--accent); }
.breadcrumb [aria-current='page'] { font-weight: 600; }

/* Product layout */
.product {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
  gap: 48px;
  align-items: start;
}
@media (max-width: 860px) { .product { grid-template-columns: 1fr; gap: 24px; } }

/* Gallery */
.gallery__stage { position: relative; background: var(--surface); border-radius: 12px; overflow: hidden; }
.gallery__image { display: block; width: 100%; height: auto; aspect-ratio: 4 / 3; }
.gallery__button {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%; border: 0;
  background: #fff; color: var(--ink); font-size: 1.2rem; cursor: pointer;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2);
}
.gallery__button--prev { left: 12px; }
.gallery__button--next { right: 12px; }
.gallery__count {
  position: absolute; left: 50%; bottom: 12px; transform: translateX(-50%);
  background: rgba(26, 26, 26, 0.85); color: #fff; padding: 2px 12px; border-radius: 999px; font-size: 0.85rem;
}

/* Buy box */
.buy-box { display: grid; gap: 20px; }
.price-row { position: relative; display: flex; align-items: center; gap: 8px; }
.price { font-size: 1.4rem; font-weight: 700; }
.info-button {
  width: 22px; height: 22px; border-radius: 50%; border: 1px solid var(--ink);
  background: #fff; font-size: 0.8rem; font-weight: 700; cursor: pointer; padding: 0;
}
.tooltip {
  position: absolute; top: calc(100% + 6px); left: 0; z-index: 5;
  width: max-content; max-width: 240px; padding: 8px 12px; border-radius: 6px;
  background: var(--ink); color: #fff; font-size: 0.9rem;
}
.description { color: var(--muted); }

.option-group { display: grid; gap: 8px; }
.option-group__label { font-weight: 600; }

.swatches { display: flex; gap: 12px; }
.swatch { cursor: pointer; border-radius: 50%; padding: 3px; border: 2px solid transparent; display: inline-flex; }
.swatch--selected { border-color: var(--ink); }
.swatch:focus-within { outline: 3px solid var(--accent); outline-offset: 2px; }
.swatch__dot { display: block; width: 36px; height: 36px; border-radius: 50%; box-shadow: inset 0 0 0 1px rgba(0,0,0,0.15); }

/* Size */
.size-picker { display: grid; gap: 8px; position: relative; }
.size-picker__header { display: flex; justify-content: space-between; align-items: baseline; }
.link-button {
  background: none; border: 0; padding: 0; color: var(--accent);
  text-decoration: underline; cursor: pointer; font: inherit;
}
.combobox-wrap { position: relative; }
.combobox {
  display: flex; justify-content: space-between; align-items: center;
  padding: 12px 14px; border: 1px solid #767676; border-radius: 6px; background: #fff; cursor: pointer;
}
.listbox {
  position: absolute; top: calc(100% + 4px); left: 0; right: 0; z-index: 4;
  margin: 0; padding: 4px 0; list-style: none; max-height: 280px; overflow-y: auto;
  background: #fff; border: 1px solid #767676; border-radius: 6px; box-shadow: 0 6px 18px rgba(0,0,0,0.15);
}
.option { display: flex; justify-content: space-between; padding: 10px 14px; cursor: pointer; }
.option--active { background: #e6eefb; }
.option[aria-disabled='true'] { cursor: not-allowed; color: #595959; }
.option__sold-out { font-size: 0.85rem; text-decoration: line-through; }
.option[aria-selected='true'] { font-weight: 700; }

/* Quantity */
.quantity { display: grid; gap: 8px; }
.quantity__controls { display: inline-flex; align-items: stretch; width: max-content; border: 1px solid #767676; border-radius: 6px; overflow: hidden; }
.quantity__controls button {
  width: 44px; font-size: 1.1rem; border: 0; background: #fff; cursor: pointer;
}
.quantity__controls button:disabled { color: #8a8a8a; cursor: not-allowed; }
.quantity__controls input {
  width: 64px; text-align: center; border: 0; border-left: 1px solid #767676; border-right: 1px solid #767676;
  font: inherit; padding: 8px 0; -moz-appearance: textfield;
}

/* Buttons and actions */
.actions { display: grid; grid-template-columns: 1fr auto; gap: 12px; }
.button {
  font: inherit; font-weight: 600; padding: 14px 20px; border-radius: 999px; cursor: pointer;
  border: 2px solid var(--ink);
}
.button--primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.button--secondary { background: #fff; color: var(--ink); }
.wishlist[aria-pressed='true'] { background: var(--ink); color: #fff; }
.message { min-height: 1.5em; font-weight: 600; }
.message--error { color: var(--error); }
.message--ok { color: var(--ok); }

/* Tabs */
.more-info { margin-top: 56px; }
.tablist { display: flex; gap: 8px; border-bottom: 1px solid var(--line); margin-bottom: 20px; }
.tab {
  font: inherit; font-weight: 600; background: none; border: 0; padding: 12px 16px; cursor: pointer;
  border-bottom: 3px solid transparent; margin-bottom: -1px; color: var(--muted);
}
.tab[aria-selected='true'] { color: var(--ink); border-bottom-color: var(--ink); }
.tabpanel { max-width: 720px; }
.tabpanel:not([hidden]) { display: grid; gap: 12px; }
.review { border-left: 3px solid var(--line); padding-left: 12px; }

/* Questions */
.questions { margin-top: 56px; max-width: 760px; }
.faq { border-top: 1px solid var(--line); }
.faq:last-child { border-bottom: 1px solid var(--line); }
.faq h3 { margin: 0; }
.faq__button {
  width: 100%; display: flex; justify-content: space-between; align-items: center;
  font: inherit; font-weight: 600; text-align: left; padding: 16px 0; background: none; border: 0; cursor: pointer;
}
.faq__answer { padding: 0 0 16px; color: var(--muted); }

/* Footer */
.site-footer { margin-top: 72px; background: #f3f4f5; padding: 40px 0 24px; }
.site-footer__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 32px; }
.site-footer h2 { font-size: 1rem; }
.social-list { display: flex; flex-wrap: wrap; gap: 16px; list-style: none; padding: 0; }
.site-footer__legal { margin-top: 32px; font-size: 0.85rem; color: var(--muted); }

/* Size guide dialog */
.dialog-backdrop {
  position: fixed; inset: 0; z-index: 50; background: rgba(0, 0, 0, 0.55);
  display: flex; align-items: center; justify-content: center; padding: 16px;
}
.dialog {
  width: min(520px, 100%); max-height: 90vh; overflow-y: auto; background: #fff; color: var(--ink);
  border-radius: 12px; padding: 24px; display: grid; gap: 16px;
}
.size-table { border-collapse: collapse; width: 100%; font-size: 0.9rem; }
.size-table caption { text-align: left; font-weight: 600; margin-bottom: 4px; }
.size-table th, .size-table td { border-bottom: 1px solid var(--line); padding: 6px 8px; text-align: left; }
.dialog__field { display: grid; gap: 6px; border: 0; padding: 0; margin: 0; }
.dialog__field input[type='number'] { font: inherit; padding: 10px; border: 1px solid #767676; border-radius: 6px; max-width: 200px; }
.dialog legend { font-weight: 600; margin-bottom: 4px; }
.inline-option { display: inline-flex; align-items: center; gap: 6px; margin-right: 16px; }
.dialog__result { font-weight: 600; }
.button--secondary.dialog-close { justify-self: start; }
